(function(){
  const M=PhaseOneModel,S=M.state(),$=id=>document.getElementById(id),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const b=(text,action,id='',cls='',disabled=false)=>`<button data-action="${action}" data-id="${esc(id)}" class="${cls}" ${disabled?'disabled':''}>${text}</button>`;
  const badge=(status,text)=>`<span class="badge ${esc(status)}">${text||({passed:'符合预期',failed:'不符合预期',running:'运行中',completed:'已完成',cancelled:'已停止',stale:'已失效'}[status]||'未运行')}</span>`;
  let route='chat',selected='weekly-report',tab='files',file='SKILL.md',createMode=false,busy=false,draft='',bound=null,messages=[],timer=null,editBuffer=null,insertId=null,insertRange=null;
  let optimizationLimit=3;
  const queries={mine:'',snippets:'',insert:''};
  const search=scope=>`<div class="search-wrap"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/></svg><input class="search" data-search="${scope}" aria-label="${scope==='mine'?'搜索技能':'搜索片段'}" placeholder="${scope==='mine'?'搜索技能名称或描述…':'搜索片段名称、说明或正文…'}" value="${esc(queries[scope])}"><button class="clear" data-action="clear" data-id="${scope}" aria-label="清除搜索" ${queries[scope]?'':'hidden'}>×</button></div>`;
  function toast(text){$('toast').textContent=text;$('toast').hidden=false;setTimeout(()=>$('toast').hidden=true,3500)}
  function dialog(title,body,footer='',wide=false){$('dialog').classList.toggle('wide',wide);$('dialog-title').textContent=title;$('dialog-body').innerHTML=body;$('dialog-footer').innerHTML=footer||b('关闭','close');if(!$('dialog').open)$('dialog').showModal()}
  function transcript(items){return items.map(m=>m.role==='tool'||m.role==='subagent'||m.role==='file'?`<div class="message"><details open><summary>${m.role==='tool'?'工具':m.role==='subagent'?'子任务':'生成文件'} · ${esc(m.name)}</summary><pre>${esc(m.content)}</pre></details></div>`:m.role==='user'?`<article class="message user"><div class="message-content">${esc(m.content)}</div></article>`:`<article class="message assistant"><div class="sender"><span class="avatar">✦</span>Claude</div><div class="message-content">${esc(m.content)}</div></article>`).join('')}
  function chat(){const body=messages.length?messages.map(m=>m.call?`<section class="stack">${transcript(m.call.result.messages)}<div class="row">${b(m.call.saved?'已保存为测评用例':'保存为测评用例','save-call',m.call.id,'quiet',m.call.saved)}${b('查看技能','open-skill',m.call.skill,'quiet')}</div></section>`:transcript([m])).join(''):transcript([{role:'assistant',content:'描述你想完成的工作，点击下方“技能创建”即可生成技能。创建后仍在当前会话，可继续调整，也可以用 /skill-name 直接调用。'}]);return `<div class="chat-shell"><div class="chat-feed" id="feed">${body}${busy?transcript([{role:'assistant',content:'正在处理（模拟）…'}]):''}</div><div class="composer-wrap"><div class="composer"><textarea id="chat-input" class="chat-input" aria-label="会话输入" placeholder="${createMode?'请描述你想创建的技能：用于什么场景、提供哪些输入、希望得到什么结果…':'输入 / 调用技能，或继续描述需要调整的内容…'}" ${busy?'disabled':''}>${esc(draft)}</textarea><div class="composer-foot"><div class="row"><button class="create-mode" data-action="create-mode" aria-pressed="${createMode}" ${busy?'disabled':''}>✦ 技能创建</button>${createMode?'<small class="muted">'+(busy?'正在创建':'已开启 · 再次点击可退出')+'</small>':''}</div><button class="send" data-action="send" aria-label="发送消息" ${busy||!draft.trim()?'disabled':''}>↑</button></div></div><p class="hint">Enter 发送 · Shift+Enter 换行${bound?' · 当前技能 '+esc(bound):''}</p></div></div>`}
  function list(){const q=queries.mine.trim().toLowerCase(),items=S.skills.filter(k=>(k.name+' '+k.title).toLowerCase().includes(q));return items.length?'<div class="skill-list">'+items.map(k=>`<button class="skill-row" data-action="open-skill" data-id="${esc(k.name)}"><span class="skill-icon">▧</span><span><strong>${esc(k.title)}</strong><small class="muted">${esc(k.name)} · 本地可编辑</small></span><span>›</span></button>`).join('')+'</div>':'<div class="empty">没有匹配的技能</div>'}
  const snippets=scope=>S.snippets.filter(x=>(x.title+' '+x.description+' '+x.body).toLowerCase().includes(queries[scope].trim().toLowerCase()));
  function snippetList(){const items=snippets('snippets');return items.length?'<div class="stack">'+items.map(x=>`<article class="snippet-card"><div><h2>${esc(x.title)}</h2><p>${esc(x.description)}</p></div>${b('查看内容','snippet-view',x.id)}${S.role==='admin'?b('编辑','snippet-edit',x.id)+b('删除','snippet-delete',x.id):''}</article>`).join('')+'</div>':'<div class="empty">没有匹配的片段，试试其他关键词。</div>'}
  function fileView(k){const value=editBuffer??k.files[file],running=S.job?.state==='running'&&S.job.skill===k.name;return `<div class="file-layout"><aside class="file-tree"><small>.claude/skills/${esc(k.name)}</small>${b('SKILL.md','file','SKILL.md',file==='SKILL.md'?'active':'')}<div>▾ evals</div>${b('　evals.json','file','evals/evals.json',file!=='SKILL.md'?'active':'')}</aside><section class="file-main"><div class="file-bar"><span>${esc(file)}</span><div class="row">${file==='SKILL.md'?b('快捷插入','insert','','',running):''}${b('保存文件','save-file','','',running)}</div></div><textarea id="editor" class="code-editor" aria-label="文件内容" ${running?'readonly':''}>${esc(value)}</textarea></section></div><p class="small muted">用例与文件为同一份数据；保存后直接生效。片段插入是正文复制，不建立关联。</p>`}
  function evalView(k){let cases=[],error='';try{cases=M.readCases(k).evals}catch(e){error=e.message}const j=k.report,running=j?.state==='running',stale=j&&j.expected!==M.stamp(k);const stateText=error||(!j?'尚未运行':running?(j.phase==='optimize'?'正在优化并保存':(j.phase==='after'?'优化后':'当前')+'测评：'+j.cursor+' / '+j.cases.length):stale?'工作区已修改；报告对应本次任务副本':(j.reason||{completed:'已完成',cancelled:'已停止',stale:'文件发生变化，已停止'}[j.state]||j.state));const status=(id,phase)=>{const r=j?.[phase].find(x=>x.id===id);return badge(r?.status,r?undefined:running&&j.phase===phase&&j.cases[j.cursor]?.id===id?'运行中':'未运行')};return `<div class="eval-heading"><h2>技能测评</h2><div class="eval-actions">${b('运行全部','run','','',running)}${b('自动优化','optimize','','',running)}<details class="add-menu"><summary>添加验证场景 ⌄</summary><div class="menu">${b('AI准备场景','case-ai','','',running)}${b('添加场景','case-add','','',running)}</div></details></div></div><p class="small muted">evals/evals.json · 后台串行运行 · 完整输出逐条查看</p><div class="note">测评和自动调优使用启动时固定的 Skill、用例及资料副本；期间修改 Skill 不会影响执行。调优回写遇到新编辑时会保留双方内容，不覆盖。</div><div class="note">${esc(stateText)}${j?.optimize?' · 已执行 '+j.iteration+' / '+j.maxIterations+' 次迭代':''}${j?.writebackConflict?' · 工作区有新编辑，调优结果仅在任务副本中，未覆盖':j?.written?' · 改动已保存，无需确认；不会自动发布':''}<div class="row">${running?b('停止','stop'):''}${j?.optimized?b('查看 Skill 修改对比','diff'):''}</div></div><div class="table-scroll"><table class="eval-table"><thead><tr><th>验证场景</th><th>预期结果</th><th>${j?.optimize?'初始前测':'运行结果'}</th>${j?.optimize?'<th>最新复测</th>':''}<th>操作</th></tr></thead><tbody><tr><td>静态检查</td><td>结构、用例格式、输入文件</td><td>${badge(j?'passed':null,j?'已通过':'未运行')}</td>${j?.optimize?'<td>'+badge(j.written?'passed':null)+'</td>':''}<td>${b('查看详情','static')}</td></tr>${(j?.cases||cases).map(c=>`<tr><td>${esc(c.prompt)}<div class="small muted">#${c.id}${k.protectedIds.includes(c.id)?' · 已发布，不能删除':''}</div></td><td>${esc(c.expected_output)}</td><td>${status(c.id,'before')}</td>${j?.optimize?'<td>'+status(c.id,'after')+'</td>':''}<td><div class="row">${b('查看详情','case-detail',c.id)}${b('编辑','case-edit',c.id,'',running)}${b('删除','case-delete',c.id,'',running||k.protectedIds.includes(c.id))}</div></td></tr>`).join('')||'<tr><td colspan="5">暂无用例，请添加验证场景，或在会话调用后保存。</td></tr>'}</tbody></table></div><p class="small muted">原型结果为预设演示，不代表真实模型测评；生产判定需独立规则及 AI 评审器。</p>`}
  function render(){const chatRoute=route==='chat';$('page-title').textContent=chatRoute?'聊天':'技能';$('navigation').innerHTML=chatRoute?'':b('我的技能','route','mine',route==='mine'||route==='detail'?'active':'')+b('片段管理','route','snippets',route==='snippets'?'active':'');if(chatRoute)$('main').innerHTML=chat();else if(route==='mine')$('main').innerHTML=`<section class="page"><div class="page-head"><div><h1>我的技能</h1><p>查看文件、维护用例、运行测评和自动优化</p></div>${b('在会话中创建技能','create-entry','','primary')}</div>${search('mine')}<div id="list-results">${list()}</div></section>`;else if(route==='snippets')$('main').innerHTML=`<section class="page"><div class="page-head"><div><h1>片段管理</h1><p>全平台共享固定正文；${S.role==='admin'?'平台管理员维护':'普通用户可查看和使用，不能维护'}</p></div>${S.role==='admin'?b('新增片段','snippet-new','','primary'):badge('','只读')}</div>${search('snippets')}<div id="list-results">${snippetList()}</div></section>`;else{const k=M.skill(S,selected);$('main').innerHTML=`<section class="page"><div class="page-head"><div>${b('← 返回我的技能','route','mine','quiet')}<h1>${esc(k.title)}</h1><p>${esc(k.name)}</p></div>${b('在会话中调用','invoke',k.name)}</div><nav class="tabs">${b('文件编辑','tab','files',tab==='files'?'active':'')}${b('测评','tab','eval',tab==='eval'?'active':'')}</nav><div class="stack">${tab==='files'?fileView(k):evalView(k)}</div></section>`}if(chatRoute)$('feed').scrollTop=$('feed').scrollHeight}
  function guardDirty(){if(editBuffer!==null&&editBuffer!==M.skill(S,selected).files[file]){toast('文件有未保存修改，请先保存，或恢复为原内容后再离开。');return false}editBuffer=null;return true}
  function caseForm(id){const k=M.skill(S,selected),c=id?M.readCases(k).evals.find(c=>c.id===+id):null;dialog(c?'编辑验证场景':'添加验证场景',`<label class="field">场景输入<textarea id="case-prompt" placeholder="例如：本周完成两场活动但没有客流明细，请生成周报。">${esc(c?.prompt||'')}</textarea></label><label class="field">预期结果<textarea id="case-expected" placeholder="例如：列出活动进展，明确缺少客流数据，不编造增长比例，并给出下周计划。">${esc(c?.expected_output||'')}</textarea></label><label class="field">检查要点（可选，每行一个）<textarea id="case-checks" placeholder="不编造业务数据&#10;明确列出缺少的材料">${esc(c?.expectations?.join('\n')||'')}</textarea></label><p class="small muted">保存即写入 evals/evals.json，不需要再次确认。附件引用可在用例文件中维护。</p>`,b('取消','close')+b('保存用例','case-save',id||'','primary'))}
  function detail(id){const k=M.skill(S,selected),j=k.report,c=j?.cases.find(c=>c.id===+id)||M.readCases(k).evals.find(c=>c.id===+id);const column=(label,r)=>`<section class="output-column"><h3>${label}</h3>${r?transcript(r.messages)+'<div class="note">'+badge(r.status)+'<p>'+esc(r.reason)+'</p></div>':'<p class="muted">尚未运行</p>'}</section>`;dialog('验证场景 #'+id,`<h3>预期结果</h3><pre class="code">${esc(c.expected_output)}</pre><h3>检查要点</h3><p>${esc(c.expectations?.join('；')||'依据预期结果判断')}</p>${j&&j.expected!==M.stamp(k)?'<p class="note">这是旧运行快照，当前文件已变化。</p>':''}<div class="output-scroll"><div class="output-grid ${j?.optimize?'compare':''}">${column(j?.optimize?'初始前测 · 完整输出':'本次运行 · 完整输出',j?.before.find(r=>r.id===+id))}${j?.optimize?column(j.iteration?'第 '+j.iteration+' 次优化后 · 完整输出':'未执行优化',j.after.find(r=>r.id===+id)):''}</div></div>`,b('关闭','close'),true)}
  function insertList(){const items=snippets('insert');return items.map(x=>b(esc(x.title),'insert-pick',x.id,x.id===insertId?'active':'')).join('')||'<p class="muted">没有匹配的片段</p>'}
  function insertDialog(){insertId=null;queries.insert='';dialog('快捷插入 · 片段',`${search('insert')}<div class="insert-grid"><div id="insert-results" class="insert-list">${insertList()}</div><div id="insert-preview"><p class="muted">选择左侧片段查看正文</p></div></div>`,b('取消','close')+b('插入正文','insert-apply','','primary',true))}
  function snippetForm(id){if(S.role!=='admin')throw Error('仅平台管理员可维护');const x=S.snippets.find(x=>x.id===id);dialog(x?'编辑片段':'新增片段',`<label class="field">片段名称<input id="sn-title" value="${esc(x?.title||'')}" placeholder="例如：事实与依据"></label><label class="field">用途说明<input id="sn-desc" value="${esc(x?.description||'')}" placeholder="用于什么业务场景"></label><label class="field">固定 Markdown 正文<textarea id="sn-body" placeholder="例如：仅依据用户提供的材料，不编造数据。">${esc(x?.body||'')}</textarea></label><p class="small muted">只允许平台通用内容，不填写租户私有资料或凭据。修改不会回写已插入的技能。</p>`,b('取消','close')+b('保存片段','snippet-save',id,'primary'))}
  async function action(a,id){
    if(a==='close')return $('dialog').close();
    if(a==='route'){if(!guardDirty())return;route=id;render();return}
    if(a==='create-entry'){if(!guardDirty())return;route='chat';createMode=true;render();$('chat-input').focus();return}
    if(a==='create-mode'){if(busy)return;createMode=!createMode;render();$('chat-input').focus();return}
    if(a==='send'){if(busy||!draft.trim())return;const text=draft;
      if(createMode){const job=M.startCreate(S,{description:text});busy=true;messages.push({role:'user',content:text});render();setTimeout(()=>{try{const k=M.finishCreate(S,job);bound=k.name;createMode=false;draft='';messages.push({role:'assistant',content:'【模拟创建完成】已调用 skill-creator，并保存到 .claude/skills/'+k.name+'/。\n初始化了 evals/evals.json，暂时没有用例。'+(job.snippets.length?'\n匹配并复制了片段：'+job.snippets.map(x=>x.title).join('、'):'\n没有匹配的片段，未强行插入。')+'\n你可以继续描述调整要求，或直接输入 /'+k.name+' 具体任务进行验证。'})}catch(e){toast(e.message)}finally{busy=false;render()}},850);return}
      const match=text.match(/^\/([a-z0-9-]+)\s+([\s\S]+)$/);if(match){const k=M.skill(S,match[1]),call=M.invocation(S,k,match[2]);messages.push({call});bound=k.name;draft='';render();return}
      if(bound){const k=M.skill(S,bound);M.saveFile(S,k,'SKILL.md',k.files['SKILL.md']+'\n## 会话补充要求\n'+text+'\n');messages.push({role:'user',content:text},{role:'assistant',content:'【模拟调整完成】要求已写入 '+bound+'/SKILL.md。可继续调用验证，旧测评结果会标记为已失效。'});draft='';render();return}
      messages.push({role:'user',content:text},{role:'assistant',content:'这是普通会话演示，不会调用 skill-creator。创建技能请先开启下方“技能创建”，或使用 /weekly-report 具体任务调用已有技能。'});draft='';render();return;
    }
    if(a==='save-call'){const call=messages.find(m=>m.call?.id===id)?.call;M.saveInvocation(S,call);render();toast('已将本次输入和参考输出保存为用例，无需再次确认');return}
    if(a==='open-skill'){if(!guardDirty())return;selected=id;file='SKILL.md';tab='files';route='detail';render();return}
    if(a==='invoke'){if(!guardDirty())return;bound=id;route='chat';createMode=false;draft='/'+id+' ';render();$('chat-input').focus();return}
    if(a==='tab'){if(!guardDirty())return;tab=id;render();return}
    if(a==='file'){if(!guardDirty())return;file=id;render();return}
    if(a==='save-file'){M.saveFile(S,M.skill(S,selected),file,$('editor').value);editBuffer=null;render();toast('文件已保存');return}
    if(a==='insert'){const editor=$('editor'),frontmatter=editor.value.match(/^---\r?\n[\s\S]*?\r?\n---(?:\r?\n|$)/);insertRange=frontmatter&&editor.selectionStart<frontmatter[0].length?[editor.value.length,editor.value.length]:[editor.selectionStart,editor.selectionEnd];insertDialog();return}
    if(a==='insert-pick'){insertId=id;const x=S.snippets.find(x=>x.id===id);$('insert-results').innerHTML=insertList();$('insert-preview').innerHTML='<h3>'+esc(x.title)+'</h3><pre class="code">'+esc(x.body)+'</pre>';$('dialog-footer').innerHTML=b('取消','close')+b('插入正文','insert-apply','','primary');return}
    if(a==='insert-apply'){const x=S.snippets.find(x=>x.id===insertId);if(!x)throw Error('请先选择片段');const editor=$('editor'),[start,end]=insertRange;editBuffer=editor.value.slice(0,start)+x.body+editor.value.slice(end);editor.value=editBuffer;$('dialog').close();editor.focus();editor.setSelectionRange(start+x.body.length,start+x.body.length);toast('片段已插入，保存文件后生效');return}
    if(a==='snippet-view'){const x=S.snippets.find(x=>x.id===id);dialog(x.title,'<pre class="code">'+esc(x.body)+'</pre>');return}
    if(a==='snippet-new'||a==='snippet-edit')return snippetForm(a==='snippet-new'?'':id);
    if(a==='snippet-save'){M.writeSnippet(S,{id,title:$('sn-title').value,description:$('sn-desc').value,body:$('sn-body').value});$('dialog').close();render();toast('公共片段已保存；已有技能不受影响');return}
    if(a==='snippet-delete'){if(S.role!=='admin')throw Error('仅平台管理员可维护');dialog('删除片段','<p>仅从公共库移除，不修改已经插入的 Skill。原型刷新可恢复。</p>',b('取消','close')+b('删除','snippet-confirm-delete',id));return}
    if(a==='snippet-confirm-delete'){M.removeSnippet(S,id);$('dialog').close();render();return}
    if(a==='case-add'||a==='case-edit')return caseForm(a==='case-add'?'':id);
    if(a==='case-save'){const k=M.skill(S,selected),input={prompt:$('case-prompt').value,expected_output:$('case-expected').value,expectations:$('case-checks').value.split('\n').map(x=>x.trim()).filter(Boolean)};if(id){const v=M.readCases(k),c=v.evals.find(c=>c.id===+id);Object.assign(c,input);M.saveFile(S,k,'evals/evals.json',JSON.stringify(v,null,2))}else M.addCase(S,k,input);$('dialog').close();render();toast('用例已保存到 evals/evals.json');return}
    if(a==='case-ai'){const k=M.skill(S,selected);M.addCase(S,k,{prompt:'【AI模拟场景】输入资料不完整时，使用 '+k.name+' 完成任务。',expected_output:'指出缺失信息，说明当前能得出的结论，不捏造数据。',expectations:['明确列出缺少的资料','没有编造业务事实']});render();toast('AI 模拟生成的场景已直接保存');return}
    if(a==='case-delete'){M.deleteCase(S,M.skill(S,selected),+id);render();return}
    if(a==='case-detail')return detail(id);
    if(a==='static'){dialog('静态检查','<p>原型检查：SKILL.md 标识、evals/evals.json 格式、附件路径与存在性。</p><p>正式实现还需大小限制、符号链接、敏感信息和危险操作扫描；此演示不是安全审计。</p>');return}
    if(a==='optimize'){dialog('自动优化设置',`<label class="field">最大迭代次数<input id="max-iterations" type="number" min="1" max="10" step="1" value="${optimizationLimit}" required><span class="small">默认 3 次，可设置 1–10 次。</span></label><p>先运行全部用例；每次迭代包含一次优化并保存，再串行复测全部用例。全部通过会提前结束，到达上限仍未通过则停止。</p><p class="small muted">初始前测不计入迭代次数；改动直接落盘，不需要再次确认。次数越多，耗时和模型用量可能越高。</p>`,b('取消','close')+b('开始优化','optimize-start','','primary'));return}
    if(a==='run'||a==='optimize-start'){const limit=a==='optimize-start'?Number($('max-iterations').value):0;M.startRun(S,M.skill(S,selected),a==='optimize-start',limit);if(a==='optimize-start'){optimizationLimit=limit;$('dialog').close()}render();timer=setInterval(()=>{M.step(S);if(route==='detail'&&tab==='eval')render();if(S.job.state!=='running'){clearInterval(timer);toast(S.job.reason||'任务已结束')}} ,650);return}
    if(a==='stop'){M.stop(S);clearInterval(timer);render();return}
    if(a==='diff'){const j=M.skill(S,selected).report;dialog('Skill 修改前后对比',`<p class="small muted">本次优化的临时对比，不是历史版本。${j.writebackConflict?'调优结果保存在任务副本，未覆盖工作区新编辑。':'改动已经保存。'}</p><div class="output-scroll"><div class="output-grid compare"><section><h3>修改前</h3><pre class="code diff-deleted">${esc(j.beforeFiles['SKILL.md'])}</pre></section><section><h3>修改后</h3><pre class="code diff-added">${esc(j.afterFiles['SKILL.md'])}</pre></section></div></div>`,b('关闭','close'),true);return}
    if(a==='clear'){queries[id]='';const input=document.querySelector('[data-search="'+id+'"]');input.value='';updateSearch(input);input.focus();return}
  }
  function updateSearch(input){const scope=input.dataset.search;queries[scope]=input.value;input.parentElement.querySelector('.clear').hidden=!input.value;if(scope==='insert'){insertId=null;$('insert-results').innerHTML=insertList();$('insert-preview').innerHTML='<p class="muted">请选择片段</p>';$('dialog-footer').innerHTML=b('取消','close')+b('插入正文','insert-apply','','primary',true)}else $('list-results').innerHTML=scope==='mine'?list():snippetList()}
  document.addEventListener('click',e=>{document.querySelectorAll('.add-menu[open]').forEach(x=>{if(!x.contains(e.target)||e.target.closest('[data-action]'))x.open=false});const target=e.target.closest('[data-action]');if(target&&!target.disabled)Promise.resolve(action(target.dataset.action,target.dataset.id)).catch(e=>toast(e.message))});
  document.addEventListener('input',e=>{if(e.target.id==='chat-input'){draft=e.target.value;document.querySelector('[data-action="send"]').disabled=busy||!draft.trim()}if(e.target.id==='editor')editBuffer=e.target.value;if(e.target.dataset.search)updateSearch(e.target)});
  document.addEventListener('keydown',e=>{if(e.target.id==='chat-input'&&e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();action('send').catch(e=>toast(e.message))}});
  $('role').addEventListener('change',e=>{if(busy||S.job?.state==='running'||!guardDirty()){e.target.value=S.role;toast('请先结束任务并保存编辑');return}S.role=e.target.value;render()});render();
})();
